import{_ as a,o,c as e,a3 as s}from"./chunks/framework.Cc-oPviL.js";const u=JSON.parse('{"title":"01 · 大模型在做什么：一个超级会「接龙」的程序","description":"","frontmatter":{},"headers":[],"relativePath":"ai/llm/01.md","filePath":"ai/llm/01.md"}'),r={name:"ai/llm/01.md"};function n(l,t,i,d,h,c){return o(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="_01-·-大模型在做什么-一个超级会「接龙」的程序" tabindex="-1">01 · 大模型在做什么：一个超级会「接龙」的程序 <a class="header-anchor" href="#_01-·-大模型在做什么-一个超级会「接龙」的程序" aria-label="Permalink to &quot;01 · 大模型在做什么：一个超级会「接龙」的程序&quot;">​</a></h1><blockquote><p><strong>学完你能说出</strong>：</p><ul><li>大模型的本质是「根据前文，预测下一个 Token 的概率」，一个一个往外吐字。</li><li>Token 是什么，为什么按 Token 计费、按 Token 算长度。</li><li>为什么它会「一本正经地胡说八道」（幻觉）。</li></ul></blockquote><h2 id="先看地图" tabindex="-1">先看地图 <a class="header-anchor" href="#先看地图" aria-label="Permalink to &quot;先看地图&quot;">​</a></h2><p>这是整个 AI 知识库的第一篇。后面所有内容（RAG、Agent）都建立在这一个事实上：<strong>模型只会接龙</strong>。</p><p>本篇讲 4 个点：① Token 是什么 → ② 接龙是怎么一步步进行的 → ③ 为什么这样设计 → ④ 幻觉从哪来。</p><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p><strong>大模型（LLM）= 一个读了海量文字、专门练「猜下一个字」的程序。</strong> 你看到的「回答」，是它一个字一个字猜出来、拼起来的。</p><h2 id="生活类比-成语接龙-输入法联想" tabindex="-1">生活类比：成语接龙 + 输入法联想 <a class="header-anchor" href="#生活类比-成语接龙-输入法联想" aria-label="Permalink to &quot;生活类比：成语接龙 + 输入法联想&quot;">​</a></h2><ul><li>你在手机上打「今天天气」，输入法会提示「真好」「怎么样」。它见过很多人这么打，所以知道后面常跟什么。</li><li>大模型就是一个<strong>超级输入法</strong>：它见过整个互联网规模的文字，所以不光能接短句，还能接出一整篇像样的文章。</li><li>区别在于：输入法只看前两三个字，大模型能<strong>看完你前面写的几千、几万字</strong>再决定下一个字。</li></ul><h2 id="一步步看-用数字走一遍" tabindex="-1">一步步看：用数字走一遍 <a class="header-anchor" href="#一步步看-用数字走一遍" aria-label="Permalink to &quot;一步步看：用数字走一遍&quot;">​</a></h2><p><strong>第 0 步：切成 Token。</strong> 模型不直接认「字」，而是认 <strong>Token（词元，模型处理文字的最小单位）</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;我爱学习&quot;  →  [我] [爱] [学习]  →  [3021, 885, 12047]   （编号是示意）</span></span></code></pre></div><p>英文里一个常见单词通常是 1 个 Token，长单词会被拆开；中文大约 1 个字对应 1 个左右的 Token，具体要看用的分词器（Tokenizer）。</p><p><strong>第 1 步：算下一个 Token 的概率。</strong> 输入「今天天气」，模型给词表里的每个 Token 打分，换算成概率：</p><table tabindex="0"><thead><tr><th>候选</th><th>概率</th></tr></thead><tbody><tr><td>真</td><td>0.45</td></tr><tr><td>很</td><td>0.30</td></tr><tr><td>怎么</td><td>0.15</td></tr><tr><td>其他所有 Token 加起来</td><td>0.10</td></tr></tbody></table><p><strong>第 2 步：选一个。</strong> 比如选中「真」，把它接到末尾，变成「今天天气真」。</p><p><strong>第 3 步：重复。</strong> 把「今天天气真」整个再喂进去，算下一个……直到模型输出一个表示「结束」的特殊 Token，或者达到长度上限。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>今天天气 → 真 → 好 → ， → 适合 → 出门 → [结束]</span></span></code></pre></div><p>所以回答是<strong>一个 Token 一个 Token 流出来</strong>的。聊天软件里文字逐渐出现，就是这个原因。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="为什么用「预测下一个-token」来训练" tabindex="-1">为什么用「预测下一个 Token」来训练？ <a class="header-anchor" href="#为什么用「预测下一个-token」来训练" aria-label="Permalink to &quot;为什么用「预测下一个 Token」来训练？&quot;">​</a></h3><ul><li><strong>问题</strong>：要让机器学会语言，最大的难点是标注数据。让人一句一句去标「这句话对不对」，成本太高。</li><li><strong>方案</strong>：直接拿现成的文字，遮住下一个字让模型去猜，猜错了就调整参数。所有文本本身就是答案，<strong>不需要人工标注</strong>。</li><li><strong>好处</strong>：可以用整个互联网的文字来训练。规模一大，模型为了猜得准，被迫学会了语法、常识，甚至推理的套路。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>因为「猜下一个词」不需要人工标注，任何文字都能当训练数据，规模可以做到极大；为了猜准，模型顺带学会了语言规律和知识。</p></div><h3 id="为什么要切成-token-而不是直接按字或按字母" tabindex="-1">为什么要切成 Token，而不是直接按字或按字母？ <a class="header-anchor" href="#为什么要切成-token-而不是直接按字或按字母" aria-label="Permalink to &quot;为什么要切成 Token，而不是直接按字或按字母？&quot;">​</a></h3><ul><li><strong>问题</strong>：按字母切，序列太长，算得慢；按完整单词切，词表会无限大，遇到新词就不认识。</li><li><strong>方案</strong>：取折中，用<strong>子词（subword）</strong>：常见词整个保留，罕见词拆成常见的片段。比如 <code>unhappiness</code> 可能拆成 <code>un</code> + <code>happi</code> + <code>ness</code>。</li><li><strong>好处</strong>：词表大小可控（几万到十几万），又不会遇到「完全不认识的词」。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>Token 是在「词表大小」和「序列长度」之间的折中：常见词整块，罕见词拆成片段，既不会词表爆炸，也不会遇到不认识的词。</p></div><h2 id="幻觉-为什么会一本正经地胡说八道" tabindex="-1">幻觉：为什么会一本正经地胡说八道 <a class="header-anchor" href="#幻觉-为什么会一本正经地胡说八道" aria-label="Permalink to &quot;幻觉：为什么会一本正经地胡说八道&quot;">​</a></h2><p><strong>幻觉（Hallucination）</strong> 指模型说出流畅、自信，但事实是错的内容。</p><p>根源就在「接龙」：模型的目标是<strong>说得像</strong>，不是<strong>说得对</strong>。你问它一本不存在的书的作者，它不会说「不知道」，而是接出一个「看起来很像作者名」的名字。</p><p>缓解办法（后面几篇会细讲）：</p><ul><li><strong>RAG</strong>：回答前先查资料，让它「照着资料说」；</li><li><strong>要求引用出处</strong>，没有出处的话就不说；</li><li>降低<strong>温度（Temperature）</strong>，减少随机性（见第 04 篇）。</li></ul><h2 id="英文术语拆解" tabindex="-1">英文术语拆解 <a class="header-anchor" href="#英文术语拆解" aria-label="Permalink to &quot;英文术语拆解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>拆开看</th><th>一句话意思</th></tr></thead><tbody><tr><td>LLM</td><td>Large 大 + Language 语言 + Model 模型</td><td>大语言模型，参数量大、读过海量文字的模型</td></tr><tr><td>Token</td><td>token = 记号、筹码</td><td>模型处理文字的最小单位，计费和长度都按它算</td></tr><tr><td>Tokenizer</td><td>token 词元 + -izer 「…化的工具」</td><td>分词器，把文字切成 Token 并编号</td></tr><tr><td>subword</td><td>sub 子 + word 词</td><td>子词，比整词小、比字母大的片段</td></tr><tr><td>Hallucination</td><td>幻觉</td><td>模型自信地说出错误内容</td></tr><tr><td>GPT</td><td>Generative 生成式 + Pre-trained 预训练的 + Transformer（一种模型结构）</td><td>OpenAI 的模型系列名，也概括了这类模型的做法</td></tr></tbody></table><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：大模型是怎么生成回答的？</strong></p><blockquote><p>自回归生成：把输入切成 Token，模型算出下一个 Token 的概率分布，按采样策略选一个，拼到末尾再继续预测，直到输出结束符或达到长度上限。所以回答是逐个 Token 生成的，这也是流式输出的原因。</p></blockquote><p><strong>Q：什么是 Token？为什么 API 按 Token 计费？</strong></p><blockquote><p>Token 是模型处理文本的最小单位，通常是子词。模型的计算量和输入、输出的 Token 数成正比，所以按 Token 计费；上下文长度上限也按 Token 算。</p></blockquote><p><strong>Q：大模型为什么会产生幻觉？怎么缓解？</strong></p><blockquote><p>因为训练目标是「预测最可能的下一个 Token」，优化的是「像不像」，不是「对不对」；遇到没见过的事实时，它会生成看似合理的内容。缓解：用 RAG 提供依据、要求引用来源、降低温度、对关键结论做校验。</p></blockquote><h2 id="容易混的地方" tabindex="-1">容易混的地方 <a class="header-anchor" href="#容易混的地方" aria-label="Permalink to &quot;容易混的地方&quot;">​</a></h2><ul><li><strong>「模型记住了答案」✗</strong>：它学到的是统计规律，不是一个可以精确查询的数据库，所以问冷门事实容易错。</li><li><strong>Token ≠ 字</strong>：中文、英文、代码的「字 / Token」比例都不一样，估算时说「大约」。</li><li><strong>模型自己不会上网</strong>：除非外部程序帮它查（RAG、工具调用），否则它只知道训练数据截止时的内容。</li></ul><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>→ 影响</strong> <a href="/study-hub/ai/llm/02">注意力与 Transformer</a>：「看完前文再猜」靠的就是注意力机制。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/llm/04">Prompt 与采样参数</a>：「选一个 Token」时怎么选，就是温度、Top-p 在管。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/rag/01">RAG 是什么</a>：既然模型会编，就先给它查好资料。</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：用一句话说清大模型生成回答的过程。</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>把输入切成 Token → 预测下一个 Token 的概率 → 选一个接到末尾 → 再预测下一个……直到结束。这叫<strong>自回归生成</strong>，所以回答是一个一个 Token 流出来的。</p></details><p><strong>Q2：为什么「预测下一个词」这么简单的任务，能训练出很聪明的模型？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为它<strong>不需要人工标注</strong>，整个互联网的文字都能拿来训练，规模极大。为了在各种文本上都猜准，模型被迫学会了语法、常识和推理套路。</p></details><p><strong>Q3：幻觉的根本原因是什么？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>训练目标是「说得像」而不是「说得对」：模型生成的是<strong>最可能的下一个 Token</strong>，遇到不知道的事实时，它会接出一个看起来合理但错误的内容，而不是说「不知道」。</p></details><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能用「输入法联想」的类比，向别人解释大模型在做什么</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能画出「切 Token → 算概率 → 选一个 → 接到末尾 → 重复」这条流程</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能说出 Token 为什么是「子词」，以及它和「字」的区别</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能解释「预测下一个词」为什么不需要人工标注</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说出幻觉的根源，以及至少 2 种缓解办法</li></ul><h2 id="下一步该懂什么" tabindex="-1">下一步该懂什么 <a class="header-anchor" href="#下一步该懂什么" aria-label="Permalink to &quot;下一步该懂什么&quot;">​</a></h2><ul><li>模型「看完前文」到底是怎么看的？→ <a href="/study-hub/ai/llm/02">注意力与 Transformer</a></li><li>「选一个 Token」有哪些选法，为什么同一个问题每次回答不一样？→ <a href="/study-hub/ai/llm/04">Prompt 与采样参数</a></li></ul>',55)])])}const k=a(r,[["render",n]]);export{u as __pageData,k as default};
